{
  "name": "todo-app",
  "version": "1.0.0",
  "private": true,
  "description": "Shared todo list web app for classmates",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "express": "^4.19.2"
  }
}

const express = require('express');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const app = express();
const PORT = process.env.PORT || 8080;
const DATA_DIR = process.env.DATA_DIR || '/data';
const DATA_FILE = path.join(DATA_DIR, 'todos.json');

function loadTodos() {
  try {
    return JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));
  } catch {
    return [];
  }
}

function saveTodos(todos) {
  fs.mkdirSync(DATA_DIR, { recursive: true });
  fs.writeFileSync(DATA_FILE, JSON.stringify(todos, null, 2));
}

let todos = loadTodos();

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

app.get('/api/todos', (req, res) => {
  res.json(todos);
});

app.post('/api/todos', (req, res) => {
  const text = (req.body.text || '').trim();
  const author = (req.body.author || '').trim().slice(0, 40);
  if (!text) return res.status(400).json({ error: 'text is required' });
  const todo = {
    id: crypto.randomUUID(),
    text: text.slice(0, 280),
    author,
    done: false,
    createdAt: new Date().toISOString(),
  };
  todos.unshift(todo);
  saveTodos(todos);
  res.status(201).json(todo);
});

app.patch('/api/todos/:id', (req, res) => {
  const todo = todos.find((t) => t.id === req.params.id);
  if (!todo) return res.status(404).json({ error: 'not found' });
  if (typeof req.body.done === 'boolean') todo.done = req.body.done;
  if (typeof req.body.text === 'string' && req.body.text.trim()) {
    todo.text = req.body.text.trim().slice(0, 280);
  }
  saveTodos(todos);
  res.json(todo);
});

app.delete('/api/todos/:id', (req, res) => {
  const before = todos.length;
  todos = todos.filter((t) => t.id !== req.params.id);
  if (todos.length === before) return res.status(404).json({ error: 'not found' });
  saveTodos(todos);
  res.status(204).end();
});

app.listen(PORT, () => {
  console.log(`todo app listening on port ${PORT}`);
});

:root {
  color-scheme: light;
  --bg: #f5f6fa;
  --card: #ffffff;
  --text: #1f2430;
  --muted: #6b7280;
  --accent: #4f46e5;
  --accent-hover: #4338ca;
  --border: #e5e7eb;
  --done: #9ca3af;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  padding: 40px 16px;
  min-height: 100vh;
}

.app {
  width: 100%;
  max-width: 560px;
  background: var(--card);
  border-radius: 16px;
  padding: 28px;
  box-shadow: 0 8px 30px rgba(0,0,0,0.06);
}

header h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
}

.subtitle {
  margin: 0 0 24px;
  color: var(--muted);
  font-size: 0.9rem;
}

#todo-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 20px;
}

#todo-form .row {
  display: flex;
  gap: 8px;
}

input[type=text] {
  flex: 1;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.95rem;
  outline: none;
}

input[type=text]:focus {
  border-color: var(--accent);
}

#author-input {
  font-size: 0.85rem;
}

button {
  cursor: pointer;
  border: none;
  border-radius: 8px;
  font-size: 0.95rem;
}

#todo-form button[type=submit] {
  background: var(--accent);
  color: white;
  padding: 10px 18px;
  font-weight: 600;
}

#todo-form button[type=submit]:hover {
  background: var(--accent-hover);
}

.filters {
  display: flex;
  gap: 6px;
  margin-bottom: 16px;
}

.filter-btn {
  background: transparent;
  color: var(--muted);
  padding: 6px 12px;
  border-radius: 999px;
  font-size: 0.85rem;
}

.filter-btn.active {
  background: var(--accent);
  color: white;
}

#todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.todo-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
}

.todo-item input[type=checkbox] {
  margin-top: 4px;
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
  cursor: pointer;
}

.todo-main {
  flex: 1;
  min-width: 0;
}

.todo-text {
  word-break: break-word;
  font-size: 0.95rem;
}

.todo-item.done .todo-text {
  text-decoration: line-through;
  color: var(--done);
}

.todo-meta {
  font-size: 0.75rem;
  color: var(--muted);
  margin-top: 2px;
}

.delete-btn {
  background: transparent;
  color: var(--muted);
  font-size: 1.1rem;
  padding: 2px 6px;
  line-height: 1;
}

.delete-btn:hover {
  color: #dc2626;
}

.empty-state {
  text-align: center;
  color: var(--muted);
  margin-top: 24px;
  font-size: 0.9rem;
}

const form = document.getElementById('todo-form');
const textInput = document.getElementById('text-input');
const authorInput = document.getElementById('author-input');
const list = document.getElementById('todo-list');
const emptyState = document.getElementById('empty-state');
const filterBtns = document.querySelectorAll('.filter-btn');

let todos = [];
let filter = 'all';

const AUTHOR_KEY = 'todo-author';
authorInput.value = localStorage.getItem(AUTHOR_KEY) || '';
authorInput.addEventListener('change', () => {
  localStorage.setItem(AUTHOR_KEY, authorInput.value.trim());
});

async function fetchTodos() {
  const res = await fetch('/api/todos');
  todos = await res.json();
  render();
}

function render() {
  list.innerHTML = '';
  const visible = todos.filter((t) => {
    if (filter === 'active') return !t.done;
    if (filter === 'done') return t.done;
    return true;
  });

  emptyState.hidden = visible.length !== 0;

  for (const todo of visible) {
    const li = document.createElement('li');
    li.className = 'todo-item' + (todo.done ? ' done' : '');

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = todo.done;
    checkbox.addEventListener('change', () => toggleDone(todo.id, checkbox.checked));

    const main = document.createElement('div');
    main.className = 'todo-main';

    const text = document.createElement('div');
    text.className = 'todo-text';
    text.textContent = todo.text;

    const meta = document.createElement('div');
    meta.className = 'todo-meta';
    const when = new Date(todo.createdAt).toLocaleString();
    meta.textContent = todo.author ? `${todo.author} · ${when}` : when;

    main.appendChild(text);
    main.appendChild(meta);

    const del = document.createElement('button');
    del.className = 'delete-btn';
    del.textContent = '✕';
    del.title = 'Delete';
    del.addEventListener('click', () => deleteTodo(todo.id));

    li.appendChild(checkbox);
    li.appendChild(main);
    li.appendChild(del);
    list.appendChild(li);
  }
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();
  const text = textInput.value.trim();
  if (!text) return;
  const author = authorInput.value.trim();
  const res = await fetch('/api/todos', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ text, author }),
  });
  const todo = await res.json();
  todos.unshift(todo);
  textInput.value = '';
  render();
});

async function toggleDone(id, done) {
  await fetch(`/api/todos/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ done }),
  });
  const todo = todos.find((t) => t.id === id);
  if (todo) todo.done = done;
  render();
}

async function deleteTodo(id) {
  await fetch(`/api/todos/${id}`, { method: 'DELETE' });
  todos = todos.filter((t) => t.id !== id);
  render();
}

filterBtns.forEach((btn) => {
  btn.addEventListener('click', () => {
    filterBtns.forEach((b) => b.classList.remove('active'));
    btn.classList.add('active');
    filter = btn.dataset.filter;
    render();
  });
});

fetchTodos();

